VALUES ('e6f7ea88-b380-5a87-89ce-6fe3567e2c29', '2026-W39', 'crypto', 'BTC $82K acceptance retest (FTR, HTF)', 'FTR, HTF', 78500.0, 80500.0, 76000, 'below', 92000, 3.6, NULL, 'after a daily close above $82,000, on a retest that holds with the ETF week still positive', 'e2231664-3be2-5a57-b74b-35dd3ac9cf5a', (SELECT id FROM macro_core.series WHERE key = 'btc'), 'BTC $82K acceptance retest (FTR, HTF): Entry $78.5K–$80.5K after a daily close above $82,000, on the retest that holds with the ETF week still positive · Invalidation $76,000 close-below · Target $92,000 · R:R ~3.6:1 · 15 - Ray Trading Blueprint. Sits under the HOLD row; the acceptance clause exists because $80K has now rejected twice and been cleared once on a squeeze. This replaces the W36–W38 old-box retest at $72K–$74K, retired after four weeks without an entry and $7K of distance from price.', 'active', TIMESTAMPTZ '2026-09-21T00:00:00Z', TIMESTAMPTZ '2026-09-21T00:00:00Z', NULL)
